<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalasi Aplikasi</title><meta name="description" content="Wizard instalasi dan pemeriksaan kebutuhan sistem aplikasi"><style>body{font-family:Arial,sans-serif;background:#101827;color:#e5e7eb;margin:0;padding:30px}.box{max-width:760px;margin:auto;background:#172338;padding:30px;border-radius:16px;box-shadow:0 20px 60px #0006}h1{margin-top:0;color:#67e8f9}h2{font-size:18px;border-bottom:1px solid #334155;padding-bottom:10px}.checks{display:grid;grid-template-columns:1fr 1fr;gap:10px}.check{padding:12px;background:#1e293b;border-radius:8px}.ok{color:#86efac}.fail{color:#fca5a5}label{display:block;margin:12px 0 5px;color:#cbd5e1}input{box-sizing:border-box;width:100%;padding:11px;border-radius:7px;border:1px solid #475569;background:#0f172a;color:white}button{margin-top:18px;padding:12px 18px;border:0;border-radius:7px;background:#06b6d4;color:#082f49;font-weight:bold;cursor:pointer}button.secondary{background:#475569;color:white;margin-left:8px}#result{margin-top:16px;padding:12px;border-radius:8px}@media(max-width:600px){body{padding:12px}.box{padding:20px}.checks{grid-template-columns:1fr}}</style></head><body><main class="box"><h1>Instalasi Aplikasi</h1><p>Pastikan kebutuhan sistem terpenuhi, lalu isi koneksi database dan akun administrator.</p><h2>1. Pemeriksaan kebutuhan sistem</h2><section class="checks"><?php foreach($requirements as $r): ?><div class="check <?= $r['ok']?'ok':'fail' ?>"><strong><?= html_escape($r['name']) ?></strong><br><?= html_escape($r['actual']) ?> <small>(<?= html_escape($r['required']) ?>)</small><?php if($r['help']): ?><br><small><?= html_escape($r['help']) ?></small><?php endif; ?></div><?php endforeach; ?></section><form id="installer"><h2>2. Konfigurasi database</h2><?php foreach(array('hostname'=>'Host','username'=>'Username','password'=>'Password','database'=>'Nama database') as $key=>$label): ?><label><?= $label ?><input type="<?= $key==='password'?'password':'text' ?>" name="<?= $key ?>" value="<?= html_escape(isset($db_config[$key])?$db_config[$key]:'') ?>" <?= $key==='password'?'':'required' ?>></label><?php endforeach; ?><h2>3. Akun administrator</h2><label>Nama<input name="admin_name" value="Administrator" required></label><label>Email<input type="email" name="admin_email" required></label><label>Username<input name="admin_username" required minlength="4"></label><label>Password<input type="password" name="admin_password" required minlength="6"></label><button type="button" id="test">Test koneksi</button><button type="submit" class="secondary">Install sekarang</button></form><div id="result" hidden></div></main><script>const f=document.querySelector('#installer'),r=document.querySelector('#result');async function send(url){r.hidden=false;r.textContent='Memproses...';let x=await fetch('<?= site_url('install/') ?>'+url,{method:'POST',body:new FormData(f)});let j=await x.json();r.textContent=j.message||'Selesai';if(j.ok&&url==='install')setTimeout(()=>location.href='<?= site_url('login') ?>',1200)}document.querySelector('#test').onclick=()=>send('test_database');f.onsubmit=e=>{e.preventDefault();if(confirm('Lanjutkan instalasi database dan data awal?'))send('install')}</script></body></html>
